<template><main class="page"><header><button @click="router.push('/points-admin')">← 用户管理</button><div><small>DOKIAI ADMIN CENTER</small><h1>学校管理</h1><p>学校编号、渠道链接、自动汇总数据与学校统计账号。</p></div><button class="primary" @click="edit()">新增学校</button></header><section v-if="editing" class="form"><input v-model="form.schoolCode" placeholder="学校编号（字母、数字、_、-）"><input v-model="form.schoolName" placeholder="学校名称"><label><input v-model="form.enabled" type="checkbox"> 启用学校</label><button class="primary" @click="save">保存</button><button @click="editing=false">取消</button></section><section class="grid"><article v-for="s in schools" :key="s.id"><header><div><small>{{ s.schoolCode }}</small><h2>{{ s.schoolName }}</h2></div><em :class="{off:!s.enabled}">{{ s.enabled?'启用':'停用' }}</em></header><div class="metrics"><span><small>注册人数</small><b>{{ s.registrationCount }}</b></span><span><small>累计充值金额</small><b>¥{{ money(s.totalRechargeAmount) }}</b></span><span><small>累计充值积分</small><b>{{ s.totalRechargePoints }}</b></span></div><code>{{ origin }}/login?college={{ s.schoolCode }}</code><footer><button @click="edit(s)">编辑</button><button @click="toggle(s)">{{ s.enabled?'停用':'启用' }}</button><button @click="openViewer(s)">创建统计账号</button></footer><div v-for="v in s.viewers||[]" :key="v.id" class="viewer"><span>{{ v.phone }} · {{ v.enabled?'已启用':'已停用' }}</span><button @click="maintain(v)">重置密码/状态</button></div></article></section><div v-if="viewerOpen" class="mask"><section class="modal"><h2>{{ viewer.userId?'维护':'创建' }}学校统计账号</h2><label>手机号<input v-model="viewer.phone" :disabled="!!viewer.userId" maxlength="11"></label><label>新密码<input v-model="viewer.password" type="password" placeholder="至少6位"></label><label><input v-model="viewer.enabled" type="checkbox"> 账号启用</label><footer><button @click="viewerOpen=false">取消</button><button class="primary" @click="saveViewer">保存</button></footer></section></div></main></template>
<script setup>import {onMounted,reactive,ref} from 'vue';import {useRouter} from 'vue-router';import {ElMessage} from 'element-plus';import {createSchool,createSchoolViewer,getSchools,setSchoolEnabled,updateSchool,updateSchoolViewer} from '../../api/rewrite';const router=useRouter(),schools=ref([]),editing=ref(false),viewerOpen=ref(false),selected=ref(null),origin=location.origin,form=reactive({id:null,schoolCode:'',schoolName:'',enabled:true}),viewer=reactive({userId:null,phone:'',password:'',enabled:true});const money=v=>Number(v||0).toLocaleString('zh-CN',{minimumFractionDigits:2});async function load(){schools.value=await getSchools()||[]}function edit(s){Object.assign(form,s?{id:s.id,schoolCode:s.schoolCode,schoolName:s.schoolName,enabled:s.enabled}:{id:null,schoolCode:'',schoolName:'',enabled:true});editing.value=true}async function save(){await(form.id?updateSchool(form.id,form):createSchool(form));editing.value=false;ElMessage.success('学校已保存');load()}async function toggle(s){await setSchoolEnabled(s.id,!s.enabled);load()}function openViewer(s){selected.value=s;Object.assign(viewer,{userId:null,phone:'',password:'',enabled:true});viewerOpen.value=true}function maintain(v){selected.value=null;Object.assign(viewer,{userId:v.id,phone:v.phone,password:'',enabled:v.enabled});viewerOpen.value=true}async function saveViewer(){if(viewer.userId)await updateSchoolViewer(viewer.userId,{password:viewer.password,enabled:viewer.enabled});else await createSchoolViewer(selected.value.id,viewer);viewerOpen.value=false;ElMessage.success('统计账号已保存');load()}onMounted(load)</script>
<style scoped>.page{min-height:100vh;padding:35px max(28px,calc((100% - 1400px)/2)) 70px;background:linear-gradient(45deg,#fbd7ea,#f7edf5 38%,#edf1f8 65%,#dcebff);color:#292b39}.page>header{display:flex;align-items:end;gap:20px}.page>header>div{flex:1}.page>header h1{margin:6px 0;font-size:40px}.page>header small,.grid small{color:#6e4fff;font-weight:800}.page button{padding:9px 13px;border:1px solid #d9d3e6;border-radius:9px;background:#fff}.primary{border:0!important;background:linear-gradient(135deg,#6e4fff,#d35ea9)!important;color:#fff}.form{display:flex;gap:10px;align-items:center;margin-top:20px;padding:18px;border-radius:18px;background:#fff}.form input{padding:10px;border:1px solid #ddd7e8;border-radius:9px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px;margin-top:18px}.grid>article{padding:22px;border:1px solid #e3deeb;border-radius:20px;background:#ffffffdf}.grid article>header{display:flex;justify-content:space-between}.grid h2{margin:5px 0}.grid em{height:max-content;padding:5px 9px;border-radius:99px;background:#e7f4ee;color:#17604c;font-style:normal}.grid em.off{background:#fff0f2;color:#c64e6e}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin:15px 0}.metrics span{display:grid;padding:11px;border-radius:10px;background:#f7f4fc}.metrics small{color:#8a91a1}.metrics b{font-size:19px}.grid code{display:block;overflow:auto;padding:10px;border-radius:8px;background:#f2eff8;color:#634fd0}.grid footer{display:flex;gap:7px;margin-top:13px}.viewer{display:flex;justify-content:space-between;align-items:center;margin-top:10px;padding:9px;border-top:1px solid #eeeaf3}.mask{position:fixed;inset:0;display:grid;place-items:center;background:#28213f52}.modal{display:grid;gap:13px;width:min(430px,90vw);padding:25px;border-radius:20px;background:#fff}.modal label{display:grid;gap:5px}.modal input{padding:10px;border:1px solid #ddd7e7;border-radius:9px}.modal footer{display:flex;justify-content:flex-end;gap:8px}@media(max-width:850px){.grid{grid-template-columns:1fr}.form{align-items:stretch;flex-direction:column}.metrics{grid-template-columns:1fr}}</style>
